// credits.json is generated by scripts/download-images.mjs — it won't
// exist until that script has been run at least once. import.meta.glob
// resolves at build time and simply returns nothing if the file is
// absent, so this never throws.
const creditsModules = import.meta.glob("../assets/products/credits.json", {
  eager: true,
  import: "default",
});
const credits = Object.values(creditsModules)[0] || {};

export default function PhotoCredit({ slug }) {
  const credit = credits[slug];
  if (!credit) return null;

  return (
    <p className="mt-2 text-xs text-ink-300">
      Photo by{" "}
      {credit.photographerUrl ? (
        <a
          href={credit.photographerUrl}
          target="_blank"
          rel="noreferrer"
          className="underline hover:text-ink-500"
        >
          {credit.photographer}
        </a>
      ) : (
        credit.photographer
      )}{" "}
      on{" "}
      <a
        href={credit.unsplashUrl || "https://unsplash.com"}
        target="_blank"
        rel="noreferrer"
        className="underline hover:text-ink-500"
      >
        Unsplash
      </a>
    </p>
  );
}
